:root { font-family: system-ui, sans-serif; color: #17283d; background: #f4f6fa; }
body { margin: 0; }
main { max-width: 760px; margin: 48px auto; padding: 24px; }
h1 { margin-top: 0; }
label { display: block; font-weight: 600; margin-bottom: 8px; }
.input-row { display: flex; gap: 12px; flex-wrap: wrap; }
input[type="text"] { flex: 1; min-width: 180px; padding: 10px; border: 1px solid #6b7889; border-radius: 4px; font: inherit; }
button { padding: 10px 16px; font: inherit; color: white; background: #2456a2; border: 0; border-radius: 4px; cursor: pointer; }
button:hover { background: #173e7b; }
button:disabled { opacity: .6; cursor: wait; }
:focus-visible { outline: 3px solid #ab6500; outline-offset: 3px; }
#projects, #tasks { margin-top: 24px; }
#task-board { margin-top: 24px; }
#task-filter { padding: 10px; font: inherit; }
label[for="task-filter"] { margin-top: 24px; }
.task-row input { width: 20px; height: 20px; flex-shrink: 0; }
.project-row, .task-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; margin-bottom: 12px; padding: 16px; border: 1px solid #c7ced9; border-radius: 6px; background: white; }
.project-row span, .task-row span { overflow-wrap: anywhere; min-width: 0; }
.project-row button { flex-shrink: 0; }
[role="alert"] { color: #9c2020; background: #fff0f0; padding: 12px; border: 1px solid #ce9393; }

