import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

export function openStore(path) {
  mkdirSync(dirname(path), { recursive: true });
  const database = new DatabaseSync(path);
  database.exec(`
    PRAGMA foreign_keys = ON;
    CREATE TABLE IF NOT EXISTS projects (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL CHECK(length(trim(name)) > 0)
    );
    CREATE TABLE IF NOT EXISTS tasks (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      project_id INTEGER NOT NULL REFERENCES projects(id),
      title TEXT NOT NULL CHECK(length(trim(title)) > 0),
      completed INTEGER NOT NULL DEFAULT 0 CHECK(completed IN (0, 1))
    );
    CREATE INDEX IF NOT EXISTS tasks_project_id ON tasks(project_id, id);
  `);
  const list = database.prepare('SELECT id, name FROM projects ORDER BY id');
  const find = database.prepare('SELECT id, name FROM projects WHERE id = ?');
  const insert = database.prepare('INSERT INTO projects (name) VALUES (?)');

  const listTasks = database.prepare('SELECT id, project_id, title, completed FROM tasks WHERE project_id = ? ORDER BY id');
  const findTask = database.prepare('SELECT id, project_id, title, completed FROM tasks WHERE project_id = ? AND id = ?');
  const insertTask = database.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
  const updateTask = database.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');
  const taskData = (row) => row && { ...row, completed: Boolean(row.completed) };

  return {
    listTasks: (projectId) => listTasks.all(projectId).map(taskData),
    createTask(projectId, title) {
      if (typeof title !== 'string' || !title.trim()) {
        throw new TypeError('Task title is required');
      }
      const result = insertTask.run(projectId, title.trim());
      return taskData(findTask.get(projectId, result.lastInsertRowid));
    },
    setTaskCompleted(projectId, taskId, completed) {
      if (typeof completed !== 'boolean') {
        throw new TypeError('Completed must be a boolean');
      }
      updateTask.run(Number(completed), projectId, taskId);
      return taskData(findTask.get(projectId, taskId));
    },
    listProjects: () => list.all(),
    getProject: (id) => find.get(id),
    createProject(name) {
      if (typeof name !== 'string' || !name.trim()) {
        throw new TypeError('Project name is required');
      }
      const result = insert.run(name.trim());
      return find.get(result.lastInsertRowid);
    },
    close: () => database.close(),
  };
}

import { createServer } from 'node:http';
import { readFileSync } from 'node:fs';

const assets = new Map([
  ['/', ['text/html; charset=utf-8', readFileSync(new URL('./public/index.html', import.meta.url))]],
  ['/app.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./public/app.js', import.meta.url))]],
  ['/style.css', ['text/css; charset=utf-8', readFileSync(new URL('./public/style.css', import.meta.url))]],
]);

function json(response, status, data) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(data));
}

async function readJson(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (Buffer.byteLength(body) > 65536) {
      const error = new Error('Request is too large');
      error.status = 413;
      throw error;
    }
  }
  try {
    return JSON.parse(body);
  } catch {
    const error = new Error('Invalid JSON');
    error.status = 400;
    throw error;
  }
}

export function createApp(store) {
  return createServer(async (request, response) => {
    try {
      const path = new URL(request.url, 'http://localhost').pathname;
      if (request.method === 'GET' && path === '/health') {
        return json(response, 200, { status: 'ok' });
      }
      if (path === '/api/projects' && request.method === 'GET') {
        return json(response, 200, store.listProjects());
      }
      if (path === '/api/projects' && request.method === 'POST') {
        const input = await readJson(request);
        if (typeof input?.name !== 'string' || !input.name.trim()) {
          return json(response, 400, { error: 'Project name is required' });
        }
        return json(response, 201, store.createProject(input.name));
      }
      const tasks = path.match(/^\/api\/projects\/([1-9]\d*)\/tasks(?:\/([1-9]\d*))?$/);
      if (tasks) {
        const projectId = Number(tasks[1]);
        if (!store.getProject(projectId)) {
          return json(response, 404, { error: 'Project not found' });
        }
        if (!tasks[2] && request.method === 'GET') {
          return json(response, 200, store.listTasks(projectId));
        }
        if (!tasks[2] && request.method === 'POST') {
          const input = await readJson(request);
          if (typeof input?.title !== 'string' || !input.title.trim()) {
            return json(response, 400, { error: 'Task title is required' });
          }
          return json(response, 201, store.createTask(projectId, input.title));
        }
        if (tasks[2] && request.method === 'PATCH') {
          const input = await readJson(request);
          if (typeof input?.completed !== 'boolean') {
            return json(response, 400, { error: 'Completed must be a boolean' });
          }
          const task = store.setTaskCompleted(projectId, Number(tasks[2]), input.completed);
          return task
            ? json(response, 200, task)
            : json(response, 404, { error: 'Task not found' });
        }
      }
      const detail = path.match(/^\/api\/projects\/([1-9]\d*)$/);
      if (request.method === 'GET' && detail) {
        const project = store.getProject(Number(detail[1]));
        return project
          ? json(response, 200, project)
          : json(response, 404, { error: 'Project not found' });
      }
      if (request.method === 'GET') {
        const asset = assets.get(/^\/projects\/[1-9]\d*$/.test(path) ? '/' : path);
        if (asset) {
          response.writeHead(200, { 'Content-Type': asset[0] });
          return response.end(asset[1]);
        }
      }
      json(response, 404, { error: 'Not found' });
    } catch (error) {
      if (!error.status) console.error(error);
      if (!response.headersSent) {
        json(response, error.status || 500, { error: error.status ? error.message : 'Internal server error' });
      } else {
        response.end();
      }
    }
  });
}

const heading = document.querySelector('#heading');
const alert = document.querySelector('#error');
const listPage = document.querySelector('#project-list');
const detailPage = document.querySelector('#project-detail');
const projects = document.querySelector('#projects');
const form = document.querySelector('#create-project');
const nameInput = document.querySelector('#project-name');
const taskForm = document.querySelector('#create-task');
const titleInput = document.querySelector('#task-title');
const taskFilter = document.querySelector('#task-filter');
const taskRows = document.querySelector('#tasks');
let projectId;
let tasks = [];

function showError(message) {
  alert.textContent = message;
  alert.hidden = !message;
}

async function api(path, options) {
  const response = await fetch(path, options);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Request failed');
  return data;
}

function appendProject(project) {
  const row = document.createElement('div');
  row.className = 'project-row';
  row.dataset.testid = 'project-row';
  const name = document.createElement('span');
  name.textContent = project.name;
  const open = document.createElement('button');
  open.type = 'button';
  open.textContent = 'Open project';
  open.addEventListener('click', () => {
    window.location.assign(`/projects/${project.id}`);
  });
  row.append(name, open);
  projects.append(row);
}

form.addEventListener('submit', async (event) => {
  event.preventDefault();
  showError('');
  const name = nameInput.value.trim();
  if (!name) {
    showError('Project name is required');
    nameInput.focus();
    return;
  }
  const button = form.querySelector('button');
  button.disabled = true;
  try {
    const project = await api('/api/projects', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name }),
    });
    appendProject(project);
    nameInput.value = '';
    nameInput.focus();
  } catch (error) {
    showError(error.message);
  } finally {
    button.disabled = false;
  }
});

document.querySelector('#back').addEventListener('click', () => window.location.assign('/'));

function renderTasks() {
  taskRows.replaceChildren();
  for (const task of tasks) {
    if (taskFilter.value === 'open' && task.completed) continue;
    if (taskFilter.value === 'completed' && !task.completed) continue;
    const row = document.createElement('div');
    row.className = 'task-row';
    row.dataset.testid = 'task-row';
    const title = document.createElement('span');
    title.textContent = task.title;
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.checked = task.completed;
    checkbox.setAttribute('aria-label', `Complete ${task.title}`);
    checkbox.addEventListener('change', async () => {
      checkbox.disabled = true;
      showError('');
      try {
        const updated = await api(`/api/projects/${projectId}/tasks/${task.id}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ completed: checkbox.checked }),
        });
        tasks = tasks.map((item) => item.id === updated.id ? updated : item);
        renderTasks();
      } catch (error) {
        checkbox.checked = task.completed;
        showError(error.message);
      } finally {
        checkbox.disabled = false;
      }
    });
    row.append(title, checkbox);
    taskRows.append(row);
  }
}

taskFilter.addEventListener('change', renderTasks);
taskForm.addEventListener('submit', async (event) => {
  event.preventDefault();
  showError('');
  const title = titleInput.value.trim();
  if (!title) {
    showError('Task title is required');
    titleInput.focus();
    return;
  }
  const button = taskForm.querySelector('button');
  button.disabled = true;
  try {
    const task = await api(`/api/projects/${projectId}/tasks`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ title }),
    });
    tasks.push(task);
    renderTasks();
    titleInput.value = '';
    titleInput.focus();
  } catch (error) {
    showError(error.message);
  } finally {
    button.disabled = false;
  }
});

async function loadPage() {
  const match = window.location.pathname.match(/^\/projects\/([1-9]\d*)$/);
  if (match) {
    detailPage.hidden = false;
    try {
      const project = await api(`/api/projects/${match[1]}`);
      heading.textContent = project.name;
      document.title = `${project.name} — Workboard`;
      projectId = project.id;
      tasks = await api(`/api/projects/${projectId}/tasks`);
      renderTasks();
      document.querySelector('#task-board').hidden = false;
    } catch (error) {
      heading.textContent = 'Project unavailable';
      showError(error.message);
    }
  } else {
    try {
      const all = await api('/api/projects');
      all.forEach(appendProject);
    } catch (error) {
      showError(error.message);
    }
    listPage.hidden = false;
  }
}

loadPage();

import test from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { once } from 'node:events';

async function launch(dbPath) {
  const child = spawn(process.execPath, ['server.js'], {
    env: { ...process.env, PORT: '0', DB_PATH: dbPath },
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  let output = '';
  let errors = '';
  child.stderr.on('data', (chunk) => { errors += chunk; });
  const base = await new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      child.kill();
      reject(new Error(`Startup timed out: ${errors}`));
    }, 5000);
    child.once('error', (error) => { clearTimeout(timer); reject(error); });
    child.once('exit', (code) => {
      clearTimeout(timer);
      reject(new Error(`Server exited (${code}): ${errors}`));
    });
    child.stdout.on('data', (chunk) => {
      output += chunk;
      const match = output.match(/listening on port (\d+)/);
      if (match) {
        clearTimeout(timer);
        resolve(`http://127.0.0.1:${match[1]}`);
      }
    });
  });
  return {
    base,
    async stop() {
      if (child.exitCode !== null || child.signalCode !== null) return;
      const exited = once(child, 'exit');
      child.kill('SIGTERM');
      await exited;
    },
  };
}

test('launch contract, validation, ordered projects, and process-restart persistence', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-test-'));
  let server;
  try {
    const dbPath = join(directory, 'nested', 'projects.sqlite');
    server = await launch(dbPath);
    const get = (path) => fetch(`${server.base}${path}`);
    const create = (name) => fetch(`${server.base}/api/projects`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name }),
    });
    const health = await get('/health');
    assert.equal(health.status, 200);
    assert.deepEqual(await health.json(), { status: 'ok' });
    assert.deepEqual(await (await get('/api/projects')).json(), []);
    for (const name of ['', ' \t\n ', null, 123]) {
      const response = await create(name);
      assert.equal(response.status, 400);
      assert.deepEqual(await response.json(), { error: 'Project name is required' });
    }
    assert.deepEqual(await (await get('/api/projects')).json(), []);
    const response = await create('  First project  ');
    assert.equal(response.status, 201);
    const first = await response.json();
    assert.equal(first.name, 'First project');
    const second = await (await create('<script>not markup</script>')).json();
    assert.notEqual(first.id, second.id);
    assert.deepEqual(await (await get('/api/projects')).json(), [first, second]);
    assert.deepEqual(await (await get(`/api/projects/${first.id}`)).json(), first);
    const page = await get(`/projects/${first.id}`);
    assert.equal(page.status, 200);
    assert.match(await page.text(), /id="project-detail"/);
    const home = await (await get('/')).text();
    assert.match(home, /<h1 id="heading">Workboard<\/h1>/);
    assert.match(home, /<label for="project-name">Project name<\/label>/);
    assert.match(home, /Create project/);
    assert.equal((await get('/api/projects/999999')).status, 404);
    const invalid = await fetch(`${server.base}/api/projects`, { method: 'POST', body: '{' });
    assert.equal(invalid.status, 400);
    const taskPath = `/api/projects/${first.id}/tasks`;
    const sendTask = (path, method, data) => fetch(`${server.base}${path}`, {
      method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data),
    });
    assert.deepEqual(await (await get(taskPath)).json(), []);
    for (const title of ['', ' \t\n ', null, 123]) {
      const invalidTask = await sendTask(taskPath, 'POST', { title });
      assert.equal(invalidTask.status, 400);
      assert.deepEqual(await invalidTask.json(), { error: 'Task title is required' });
    }
    assert.deepEqual(await (await get(taskPath)).json(), []);
    const createdTask = await sendTask(taskPath, 'POST', { title: '  First task  ' });
    assert.equal(createdTask.status, 201);
    const task = await createdTask.json();
    assert.equal(task.title, 'First task');
    assert.equal(task.completed, false);
    const nextTask = await (await sendTask(taskPath, 'POST', { title: '<b>Second task</b>' })).json();
    assert.deepEqual(await (await get(taskPath)).json(), [task, nextTask]);
    const otherTaskPath = `/api/projects/${second.id}/tasks`;
    assert.deepEqual(await (await get(otherTaskPath)).json(), []);
    assert.equal((await sendTask(`${otherTaskPath}/${task.id}`, 'PATCH', { completed: true })).status, 404);
    assert.equal((await sendTask('/api/projects/999999/tasks', 'POST', { title: 'Orphan' })).status, 404);
    for (const completed of [null, 1, 'true']) {
      assert.equal((await sendTask(`${taskPath}/${task.id}`, 'PATCH', { completed })).status, 400);
    }
    const completed = await (await sendTask(`${taskPath}/${task.id}`, 'PATCH', { completed: true })).json();
    assert.equal(completed.completed, true);
    const reopened = await (await sendTask(`${taskPath}/${task.id}`, 'PATCH', { completed: false })).json();
    assert.deepEqual(reopened, task);
    await sendTask(`${taskPath}/${task.id}`, 'PATCH', { completed: true });
    const detailHtml = await (await get(`/projects/${first.id}`)).text();
    assert.match(detailHtml, /<label for="task-title">Task title<\/label>/);
    assert.match(detailHtml, /Create task/);
    assert.match(detailHtml, /<label for="task-filter">Task filter<\/label>/);
    for (const option of ['All', 'Open', 'Completed']) {
      assert.ok(detailHtml.includes(`>${option}</option>`));
    }
    await server.stop();
    server = await launch(dbPath);
    assert.deepEqual(await (await get('/api/projects')).json(), [first, second]);
    assert.deepEqual(await (await get(`/api/projects/${first.id}`)).json(), first);
    assert.deepEqual(await (await get(taskPath)).json(), [completed, nextTask]);
    assert.deepEqual(await (await get(otherTaskPath)).json(), []);
    assert.equal((await get(`/projects/${first.id}`)).status, 200);
  } finally {
    if (server) await server.stop();
    await rm(directory, { recursive: true, force: true });
  }
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { runInNewContext } from 'node:vm';

// Small DOM boundary double: exercise the actual browser script without dependencies.
class Element {
  constructor() {
    this.children = [];
    this.listeners = {};
    this.dataset = {};
    this.attributes = {};
    this.value = '';
    this.hidden = true;
  }
  addEventListener(name, callback) { this.listeners[name] = callback; }
  append(...children) { this.children.push(...children); }
  replaceChildren() { this.children = []; }
  setAttribute(name, value) { this.attributes[name] = value; }
  querySelector() { return this.button ??= new Element(); }
  focus() {}
  async trigger(name) { await this.listeners[name]({ preventDefault() {} }); }
}

const settle = () => new Promise((resolve) => setImmediate(resolve));

test('project UI creates trimmed tasks, filters in order, and saves completion both ways', async () => {
  const elements = new Map();
  const element = (selector) => {
    if (!elements.has(selector)) elements.set(selector, new Element());
    return elements.get(selector);
  };
  element('#task-filter').value = 'all';
  let storedTasks = [
    { id: 1, title: 'First', completed: false },
    { id: 2, title: '<b>Second</b>', completed: true },
  ];
  const requests = [];
  const context = {
    document: { querySelector: element, createElement: () => new Element() },
    window: { location: { pathname: '/projects/7', assign() {} } },
    fetch: async (path, options = {}) => {
      requests.push({ path, options });
      let data;
      if (path === '/api/projects/7') data = { id: 7, name: 'Project' };
      else if (options.method === 'POST') {
        data = { id: 3, ...JSON.parse(options.body), completed: false };
        storedTasks.push(data);
      } else if (options.method === 'PATCH') {
        const id = Number(path.split('/').at(-1));
        data = { ...storedTasks.find((task) => task.id === id), ...JSON.parse(options.body) };
        storedTasks = storedTasks.map((task) => task.id === id ? data : task);
      } else data = storedTasks;
      return { ok: true, json: async () => structuredClone(data) };
    },
  };
  runInNewContext(await readFile(new URL('../public/app.js', import.meta.url), 'utf8'), context);
  await settle();
  const rows = () => element('#tasks').children;
  const titles = () => rows().map((row) => row.children[0].textContent);
  assert.equal(element('#heading').textContent, 'Project');
  assert.deepEqual(titles(), ['First', '<b>Second</b>']);
  assert.equal(rows()[0].dataset.testid, 'task-row');
  assert.equal(rows()[0].children[1].attributes['aria-label'], 'Complete First');
  assert.equal(rows()[1].children[1].checked, true);

  element('#task-title').value = '  \t ';
  await element('#create-task').trigger('submit');
  assert.equal(element('#error').textContent, 'Task title is required');
  assert.equal(element('#error').hidden, false);
  assert.equal(requests.length, 2);
  assert.equal(rows().length, 2);

  element('#task-title').value = '  Third  ';
  await element('#create-task').trigger('submit');
  assert.deepEqual(titles(), ['First', '<b>Second</b>', 'Third']);
  assert.equal(element('#task-title').value, '');
  assert.equal(requests.at(-1).path, '/api/projects/7/tasks');

  element('#task-filter').value = 'open';
  await element('#task-filter').trigger('change');
  assert.deepEqual(titles(), ['First', 'Third']);
  const firstCheckbox = rows()[0].children[1];
  firstCheckbox.checked = true;
  await firstCheckbox.trigger('change');
  assert.equal(requests.at(-1).path, '/api/projects/7/tasks/1');
  assert.deepEqual(titles(), ['Third']);

  element('#task-filter').value = 'completed';
  await element('#task-filter').trigger('change');
  assert.deepEqual(titles(), ['First', '<b>Second</b>']);
  const reopenCheckbox = rows()[0].children[1];
  reopenCheckbox.checked = false;
  await reopenCheckbox.trigger('change');
  assert.deepEqual(titles(), ['<b>Second</b>']);

  element('#task-filter').value = 'all';
  await element('#task-filter').trigger('change');
  assert.deepEqual(titles(), ['First', '<b>Second</b>', 'Third']);
  assert.equal(rows()[0].children[1].checked, false);
});

